public class DocumentTest {

    @Test
    public void createShellDocumentTest() {
        Connection connection = new Connection();
        Document document = Document.createShell("https://www.example.com");
        assertEquals("https://www.example.com", document.location());
    }

    @Test
    public void locationReturnEmptyStringTest() {
        Document document = Document.createShell("");
        assertEquals("", document.location());
    }

    @Test
    public void createElementWithNullTagNameTest_Fails() {
        assertThrows(NullPointerException.class, () -> Document.createElement(null));
    }

    @Test
    public void createElementWithValidTagNameTest_ReturnsElement() {
        String tagName = "div";
        Element element = Document.createElement(tagName);
        assertNotNull(element);
    }

    @Test
    public void textWithNullValueTest_ReturnsEmptyString() {
        Document document = new Document("https://www.example.com");
        assertEquals("", document.text(null));
    }

    @Test
    public void titleWithNullValueTest_ReturnsEmptyString() {
        Document document = new Document("https://www.example.com");
        assertEquals("", document.title(null));
    }

    @Test
    public void updateMetaCharsetElementFalseUpdatesMetaCharsetElementTest() {
        Document document = new Document("https://www.example.com");
        boolean updated = document.updateMetaCharsetElement();
        assertFalse(updated);
    }

    @Test
    public void updateMetaCharsetElementTrueUpdatesMetaCharsetElementTest() {
        Document document = new Document("https://www.example.com");
        document.charset(Charset.forName("UTF-8"));
        boolean updated = document.updateMetaCharsetElement();
        assertTrue(updated);
    }

    @Test
    public void cloneDocumentReturnsSameInstanceTest() {
        Document document = new Document("https://www.example.com");
        Document cloned = document.clone();
        assertSame(document, cloned);
    }

    @Test
    public void shallowCloneDocumentReturnsNewInstanceOfSameClassTest() throws Exception {
        Document document = new Document("https://www.example.com");
        Document cloned = document.shallowClone();
        assertTrue(cloned instanceof Document);
        assertEquals(1, cloned.toString().split(",").length);
    }

    @Test
    public void createDocumentFromParserTest_RaisesNullPointerExceptionWhenParserIsNull() {
        Parser parser = null;
        assertThrows(NullPointerException.class, () -> new Document(parser));
    }

    @Test
    public void createDocumentFromConnectionAndParserTest_ReturnsDocumentWithCorrectLocationAndCharset() throws Exception {
        Connection connection = new Connection();
        Parser parser = Parser.parse("https://www.example.com", "UTF-8");
        Document document = Document.createShell(connection, parser);
        assertEquals("https://www.example.com", document.location());
        assertEquals(Charset.forName("UTF-8"), document.charset());
    }
}
